import React, { useState, useEffect } from 'react';
import { getProjetos } from '../api/ClienteApi';

const ProjetoList = ({ clienteId }) => {
  const [projetos, setProjetos] = useState([]);

  useEffect(() => {
    const fetchProjetos = async () => {
      try {
        const projetosData = await getProjetos(clienteId);
        setProjetos(projetosData);
      } catch (error) {
        console.error('Erro ao buscar projetos', error);
      }
    };

    fetchProjetos();
  }, [clienteId]);

  return (
    <div>
      <h3>Projetos de Cliente {clienteId}</h3>
      <ul>
        {projetos.map((projeto) => (
          <li key={projeto.id}>{projeto.nome}</li>
        ))}
      </ul>
    </div>
  );
};

export default ProjetoList;
